sp_widget.client_script:
api.controller=function($scope){
    var c=this;
    c.searchText='';

    c.search=function(){
        $scope.page.deptSearch = c.searchText;
    };

    c.clear=function(){
        c.searchText='';
        $scope.page.deptSearch='';
    };
};

sp_widget.css:
.dept-filter-bar{
  display:grid;
  grid-template-columns:1fr auto;
  gap:14px;
  align-items:center;
  background:#FFFFFF;
  padding:18px 22px;
  border-radius:24px;
  box-shadow:0 18px 42px rgba(8,24,74,.06);
  margin-top:20px;
}
.dept-search-input{
  height:54px;
  width:100%;
  border:none;
  background:#F5F7FD;
  border-radius:16px;
  padding:0 18px;
  font-size:15px;
  color:#07195A;
  outline:none;
}

.dept-search-input::placeholder{
  color:#AAB2C8;
}

.dept-reset-btn{
  height:54px;
  padding:0 32px;
  border:none;
  border-radius:16px;
  background:linear-gradient(90deg,#24D3A1,#41D4C5);
  color:white;
  font-size:15px;
  font-weight:800;
  cursor:pointer;
  transition:.25s;
  white-space:nowrap;
}

.dept-reset-btn:hover{
  transform:translateY(-2px);
  box-shadow:0 14px 28px rgba(36,211,161,.25);
}

@media(max-width:768px){
  .dept-filter-bar{
    grid-template-columns:1fr;
    gap:12px;
    padding:16px;
    border-radius:20px;
  }
  .dept-search-input{
    height:48px;
    font-size:14px;
  }
  .dept-reset-btn{
    height:48px;
    font-size:14px;
    width:100%;
  }
}
